const html = `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OpenGL Exam Reviewer</title>
<style>
:root{--bg:#0b1020;--panel:#121a2d;--panel2:#18223a;--text:#e9eefc;--muted:#94a3c7;--accent:#7c9cff;--accent2:#6ee7c6;--danger:#ff7c8d;--border:#263453;--code:#0a0f1c}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0%,#162650 0,#0b1020 40%);color:var(--text);font:15px/1.5 system-ui,-apple-system,Segoe UI,sans-serif}body.light{--bg:#eef3fb;--panel:#fff;--panel2:#e9eef8;--text:#182033;--muted:#52617c;--accent:#345eea;--accent2:#087f63;--border:#ccd6e8;--code:#101827;background:#eef3fb}.app{max-width:1500px;margin:auto;padding:22px}.top{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.eyebrow{color:var(--accent2);font-weight:800;letter-spacing:.12em;text-transform:uppercase;font-size:12px}.title{font-size:clamp(28px,4vw,48px);line-height:1.05;margin:6px 0}.sub{color:var(--muted);max-width:760px}.actions,.chips,.toolbar{display:flex;flex-wrap:wrap;gap:8px;align-items:center}.btn,.select,.input{border:1px solid var(--border);background:var(--panel);color:var(--text);border-radius:10px;padding:10px 13px;cursor:pointer}.btn:hover{border-color:var(--accent);transform:translateY(-1px)}.btn.primary{background:var(--accent);color:#fff;border-color:transparent}.btn.ghost{background:transparent}.grid{display:grid;grid-template-columns:280px 1fr;gap:18px;margin-top:20px}.side,.card,.stat{background:color-mix(in srgb,var(--panel) 94%,transparent);border:1px solid var(--border);border-radius:16px}.side{padding:14px;height:max-content;position:sticky;top:16px}.nav{display:grid;gap:6px;margin:12px 0}.nav button{text-align:left}.nav button.active{background:var(--panel2);border-color:var(--accent)}.content{min-width:0}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:14px}.stat{padding:13px}.stat b{font-size:23px;display:block}.stat span{color:var(--muted);font-size:12px}.card{padding:18px;margin-bottom:14px}.card h2,.card h3{margin-top:0}.split{display:grid;grid-template-columns:minmax(0,1fr) minmax(280px, .8fr);gap:14px}.code{background:var(--code);border:1px solid #26314a;border-radius:12px;padding:14px;overflow:auto;white-space:pre;font:12px/1.55 ui-monospace,SFMono-Regular,Consolas,monospace;max-height:560px}.blank{width:92px;border:1px solid var(--accent);background:#263354;color:#fff;border-radius:5px;padding:2px 5px;font:inherit}.blank:focus{outline:2px solid var(--accent2)}.blank.correct{border-color:#22c55e;background:#063b2a;color:#b7ffd7}.blank.incorrect{border-color:#ef4444;background:#4b1018;color:#ffd0d6}.blank-result{display:inline-block;margin-left:8px;font:12px/1.4 system-ui,sans-serif}.blank-result.correct{color:#6ee7c6}.blank-result.incorrect{color:#ff9aa7}.tok-key{color:#ff9ac2}.tok-gl{color:#76d9ff}.tok-num{color:#ffd27d}.tok-comment{color:#6d7c99}.shot{width:100%;max-height:420px;object-fit:contain;background:#060a13;border-radius:12px;border:1px solid var(--border)}.small{color:var(--muted);font-size:13px}.tag{display:inline-block;padding:4px 8px;border-radius:999px;background:var(--panel2);color:var(--muted);font-size:12px;margin:2px}.answer{margin-top:12px;padding:12px;border-radius:10px;background:var(--panel2);border-left:4px solid var(--accent2)}.wrong{border-left-color:var(--danger)}.quiz-options{display:grid;gap:8px}.quiz-options label{padding:10px;border:1px solid var(--border);border-radius:10px;cursor:pointer}.quiz-options label:hover{background:var(--panel2)}.progress{height:8px;background:var(--panel2);border-radius:99px;overflow:hidden}.progress i{display:block;height:100%;background:linear-gradient(90deg,var(--accent),var(--accent2));width:0}.hide{display:none!important}.source-browser{margin-top:12px}.source-browser .source-list{max-height:46vh;overflow:auto;padding-right:2px}.source-list{display:grid;gap:8px;max-height:480px;overflow:auto}.source-item{padding:9px;border:1px solid var(--border);border-radius:10px;cursor:pointer;font-size:13px}.source-item:hover{border-color:var(--accent)}.flash{min-height:220px;display:grid;place-items:center;text-align:center;font-size:22px}.order-list{display:grid;gap:8px}.order-item{padding:12px;background:var(--panel2);border:1px solid var(--border);border-radius:10px;cursor:grab}.notice{padding:10px 12px;border-radius:10px;background:#243354;color:#dce7ff}.footer{color:var(--muted);font-size:12px;padding:16px 0} @media(max-width:950px){.grid{grid-template-columns:1fr}.side{position:static}.split{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}}
</style></head><body><div class="app"><header class="top"><div><div class="eyebrow">Offline • Modules 1–4 • Exam prep</div><div class="title">OpenGL Exam Reviewer</div><div class="sub">A source-grounded study desk built from your actual C++ activities and matched output screenshots. Everything is embedded in this file—no server or internet required.</div></div><div class="actions"><button class="btn" id="theme">☼ Theme</button><button class="btn" id="resetProgress">Reset progress</button></div></header>
<div class="grid"><aside class="side"><input class="input" id="search" placeholder="Search code, topics…" style="width:100%"><div class="toolbar" style="margin-top:8px"><select class="select" id="moduleFilter"><option value="all">All modules</option><option>Module1</option><option>Module2</option><option>Module3</option><option>Module4</option></select><select class="select" id="activityFilter"><option value="all">All activities</option></select></div><nav class="nav" id="nav"></nav><div id="sourceBrowser"></div><div class="small" style="margin-top:12px">Built from <b>${sources.length}</b> source files. Source code is preserved verbatim.</div></aside><main class="content"><div class="stats"><div class="stat"><b id="statScore">0%</b><span>overall accuracy</span></div><div class="stat"><b id="statAnswered">0</b><span>answered</span></div><div class="stat"><b id="statWeak">—</b><span>weak topic</span></div><div class="stat"><b id="statStreak">0</b><span>current streak</span></div></div><section id="view"></section><div class="footer">Offline reviewer • Progress is saved in this browser via localStorage. Double-click this HTML file anytime to study.</div></main></div></div>
<script>const DB=${payload};</script><script>
const S=DB.sources,Q=DB.questions,F=DB.flashcards,EQ=DB.establishedQuizzes||[];const state=JSON.parse(localStorage.getItem('ogl-reviewer-progress')||'{"answered":0,"correct":0,"wrong":[],"topics":{},"seen":{},"theme":"dark"}');let mode='learn', requestedSourceId=null, current=null, quizPool=[], quizIndex=0, fillPool=[], fillIndex=0, flashPool=[], flashIndex=0, establishedPool=[], establishedIndex=0, timer=null, mockEnd=0;
const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
function save(){localStorage.setItem('ogl-reviewer-progress',JSON.stringify(state));renderStats()};function renderStats(){const pct=state.answered?Math.round(state.correct/state.answered*100):0;$('#statScore').textContent=pct+'%';$('#statAnswered').textContent=state.answered;const top=Object.entries(state.topics).sort((a,b)=>b[1]-a[1])[0];$('#statWeak').textContent=top?top[0]:'—';$('#statStreak').textContent=state.streak||0};
function nav(){const items=[['learn','Learn Mode'],['fill','Fill-in-the-Blank'],['mock','Mock Exam'],['flash','Flashcards'],['mistakes','Mistakes & Progress']];$('#nav').innerHTML=items.map(x=>'<button class="btn '+(mode===x[0]?'active':'')+'" data-mode="'+x[0]+'">'+x[1]+'</button>').join('');document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render()})};
function filters(){const acts=[...new Set(S.filter(s=>$('#moduleFilter').value==='all'||s.module===$('#moduleFilter').value).map(s=>s.activity))];$('#activityFilter').innerHTML='<option value="all">All activities</option>'+acts.map(a=>'<option>'+esc(a)+'</option>').join('')};
function pickSource(){let f=S.filter(s=>($('#moduleFilter').value==='all'||s.module===$('#moduleFilter').value)&&($('#activityFilter').value==='all'||s.activity===$('#activityFilter').value));const q=($('#search').value||'').toLowerCase();if(q)f=f.filter(s=>(s.id+s.code).toLowerCase().includes(q));return f};
function sourceCard(s){return '<div class="split"><div><div class="small">'+esc(s.module+' / '+s.activity+' / '+s.file)+'</div><pre class="code">'+s.html+'</pre></div><div>'+(s.image?'<img class="shot" src="'+s.image+'" alt="'+esc(s.imageName||'output screenshot')+'">':'<div class="notice">No matching screenshot was found for this source file.</div>')+'<p class="small">Matching asset: '+esc(s.imageName||'none')+'</p></div></div>'};
function renderSourceBrowser(items,title,onSelect){$('#sourceBrowser').innerHTML='<div class="source-browser"><div class="small"><b>'+esc(title)+'</b> · '+items.length+' items</div><div id="sourceList" class="source-list">'+items.map((x,i)=>'<div class="source-item" data-index="'+i+'"><b>'+esc(x.label)+'</b><span class="small"> · '+esc(x.meta)+'</span></div>').join('')+'</div></div>';document.querySelectorAll('#sourceList .source-item').forEach(x=>x.onclick=()=>onSelect(+x.dataset.index))}
function renderLearn(){const list=pickSource();let currentIndex=requestedSourceId?Math.max(0,list.findIndex(s=>s.id===requestedSourceId)):0;requestedSourceId=null;$('#view').innerHTML='<div id="sourceDetail"></div>';const showDetail=(i)=>{if(!list.length)return;currentIndex=(i+list.length)%list.length;const s=list[currentIndex];$('#sourceDetail').innerHTML='<div class="card"><div class="toolbar"><div><h2 style="margin:0">Learn Mode</h2><div class="small">Source '+(currentIndex+1)+' of '+list.length+' · '+esc(s.file)+'</div></div><div class="actions"><button class="btn" id="toggleCode">Hide code</button><button class="btn" id="randomSource">Random source</button><button class="btn" id="prevSource">← Previous</button><button class="btn primary" id="nextSource">Next →</button></div></div><div class="chips" style="margin:12px 0"><span class="tag">glClearColor → background</span><span class="tag">glBegin/glEnd → primitives</span><span class="tag">glutDisplayFunc → redraw callback</span><span class="tag">glDrawElements → indexed arrays</span></div>'+sourceCard(s)+'<h3>What to notice</h3><p class="small">Look for setup in <code>main</code>, callback registration, frame clearing, primitive boundaries, vertex/color state, and any input or animation callback. This explanation is intentionally tied to the real file rather than replacing it with generic code.</p></div>';$('#toggleCode').onclick=()=>document.querySelectorAll('.code').forEach(x=>x.classList.toggle('hide'));$('#randomSource').onclick=()=>showDetail(Math.floor(Math.random()*list.length));$('#prevSource').onclick=()=>showDetail(currentIndex-1);$('#nextSource').onclick=()=>showDetail(currentIndex+1);scrollTo(0,0)};renderSourceBrowser(list.map(s=>({label:s.file,meta:s.module+' / '+s.activity,id:s.id})), 'Learn Mode', i=>{requestedSourceId=list[i].id;showDetail(i)});if(list.length)showDetail(currentIndex)};
function record(ok,topic,q){state.answered++;if(ok){state.correct++;state.streak=(state.streak||0)+1}else{state.streak=0;state.wrong.unshift({...q,answer:q.answer});state.wrong=state.wrong.slice(0,100)}state.topics[topic]=(state.topics[topic]||0)+(ok?0:1);save()}
function answerBox(q,topic,answer,explanation,ref,ok){return '<div class="answer '+(ok?'':'wrong')+'"><b>'+(ok?'Correct ✓':'Not quite')+'</b><br><b>Correct answer:</b> '+esc(answer)+'<br><span>'+esc(explanation)+'</span><br><span class="small">'+esc(topic)+' · '+esc(ref||'OpenGL concepts')+'</span></div>'}
function quizQuestion(q,kind){current={q,kind};let input=kind==='mcq'?'<div class="quiz-options">'+[q[1],q[1]==='glClear'?'glFlush':'glBegin and glEnd',q[1]==='glClearColor'?'glClear':'glVertex2f',q[1]==='a redraw'?'a window resize':'a shader program'].sort(()=>Math.random()-.5).map((a,i)=>'<label><input type="radio" name="ans" value="'+esc(a)+'"> '+esc(a)+'</label>').join('')+'</div>':'<input class="input" id="answer" placeholder="Type your answer…" style="width:100%">';return '<div class="card"><div class="small">'+kind.toUpperCase()+' · '+esc(q[3]||'OpenGL concepts')+'</div><h2>'+esc(q[0])+'</h2>'+input+'<div class="toolbar" style="margin-top:12px"><button class="btn primary" id="check">Check Answer</button><button class="btn" id="newQ">New Question</button><button class="btn" id="shuffle">Shuffle Questions</button><button class="btn" id="resetQuiz">Reset Quiz</button></div><div id="feedback"></div></div>'}
function nextQuiz(){if(!quizPool.length||quizIndex>=quizPool.length){quizPool=Q.slice().sort(()=>Math.random()-.5);quizIndex=0}const q=quizPool[quizIndex++];$('#view').innerHTML=quizQuestion(q,mode==='mcq'?'mcq':'fill');$('#check').onclick=()=>{const ans=mode==='mcq'?document.querySelector('input[name=ans]:checked')?.value:$('#answer').value.trim();if(!ans){$('#feedback').innerHTML='<div class="answer wrong">Enter or select an answer first.</div>';return}const ok=ans.toLowerCase()===String(q[1]).toLowerCase()||String(q[1]).toLowerCase().includes(ans.toLowerCase())&&ans.length>3;record(ok,q[3]||'OpenGL concepts', {question:q[0],answer:q[1]});$('#feedback').innerHTML=answerBox(q,q[3]||'OpenGL concepts',q[1],q[2],q[4]||'Concept bank',ok)};$('#newQ').onclick=nextQuiz;$('#shuffle').onclick=()=>{quizPool=Q.slice().sort(()=>Math.random()-.5);quizIndex=0;nextQuiz()};$('#resetQuiz').onclick=()=>{quizPool=[];quizIndex=0;nextQuiz()}}
function makeBlankQuiz(s,variant=0){
  const lines=s.code.split(/\\r?\\n/);let inBlockComment=false;
  const codeLines=lines.map(line=>{let x=line;if(inBlockComment){const end=x.indexOf('*/');if(end<0)return '';x=x.slice(end+2);inBlockComment=false}const start=x.indexOf('/*');if(start>=0){const end=x.indexOf('*/',start+2);if(end>=0)x=x.slice(0,start)+x.slice(end+2);else{inBlockComment=true;x=x.slice(0,start)}}return x.split('//')[0]});
  const codeText=codeLines.join('\\n');
  const raw=[...new Set(codeText.match(/glut[A-Za-z0-9_]+|gl[A-Za-z0-9_]+|GL_[A-Z0-9_]+/g)||[])];
  const gl=raw.filter(x=>/^(glut|gl)[A-Z]/.test(x));
  const constants=raw.filter(x=>/^GL_[A-Z0-9_]+$/.test(x)&&x!=='GL_SILENCE_DEPRECATION');
  const calls=[...codeText.matchAll(/\\b(?:glut|gl)[A-Z][A-Za-z0-9_]*\\s*\\(([^)]*)\\)/g)].map(x=>x[1]).join(',');
  const numbers=[...new Set(calls.match(/(?:0[xX][0-9A-Fa-f]+|[-+]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:f)?)/g)||[])];
  const callbackNames=['display','keyboard','specialKeys','mouse','motion','passiveMotion','reshape','timer','idle','menu'];
  const callbacks=[...new Set(callbackNames.filter(x=>new RegExp('\\\\b'+x+'\\\\b').test(calls)).concat((calls.match(/\\b(?:argc|argv|indices|colors?|vertices?|triangleVertex|quadVertex|pointVertex|[A-Za-z_][A-Za-z0-9_]*Array)\\b/g)||[])))];
  const groups=[gl,constants,callbacks,numbers,[...new Set(gl.concat(constants,callbacks,numbers))]];let chosen=[];const primary=groups[variant%groups.length];
  chosen.push(...primary.slice(0,6));
  for(const group of groups)for(const token of group)if(chosen.length<6&&!chosen.includes(token))chosen.push(token);
  const answers=[];let html=text.map((line)=>{let out=esc(line);for(const token of chosen){if(answers.find(a=>a.token===token))continue;const safe=esc(token);if(out.includes(safe)){const n=answers.length;answers.push({token,answer:token});out=out.replace(safe,'<input class="blank" data-i="'+n+'" placeholder="…"><span class="blank-result" data-r="'+n+'"></span>');break}}return out}).join('\\n');
  return {html,answers,source:s};
}
function makeFocusedBlankQuiz(s,variant=0){
  const lines=s.code.split(/\\r?\\n/);let inBlockComment=false;
  const codeLines=lines.map(line=>{let x=line;if(inBlockComment){const end=x.indexOf('*/');if(end<0)return '';x=x.slice(end+2);inBlockComment=false}const start=x.indexOf('/*');if(start>=0){const end=x.indexOf('*/',start+2);if(end>=0)x=x.slice(0,start)+x.slice(end+2);else{inBlockComment=true;x=x.slice(0,start)}}return x.split('//')[0]});
  const codeText=codeLines.join('\\n');
  const raw=[...new Set(codeText.match(/glut[A-Za-z0-9_]+|gl[A-Za-z0-9_]+|GL_[A-Z0-9_]+/g)||[])];
  const gl=raw.filter(x=>/^(glut|gl)[A-Z]/.test(x));
  const constants=raw.filter(x=>/^GL_[A-Z0-9_]+$/.test(x)&&x!=='GL_SILENCE_DEPRECATION');
  const calls=[...codeText.matchAll(/\\b(?:glut|gl)[A-Z][A-Za-z0-9_]*\\s*\\(([^)]*)\\)/g)].map(x=>x[1]).join(',');
  const numbers=[...new Set(calls.match(/(?:0[xX][0-9A-Fa-f]+|[-+]?(?:\\d+(?:\\.\\d*)?|\\.\\d+)(?:f)?)/g)||[])];
  const callbackNames=['display','keyboard','specialKeys','mouse','motion','passiveMotion','reshape','timer','idle','menu'];
  const callbacks=[...new Set(callbackNames.filter(x=>new RegExp('\\\\b'+x+'\\\\b').test(calls)).concat((calls.match(/\\b(?:argc|argv|indices|colors?|vertices?|triangleVertex|quadVertex|pointVertex|[A-Za-z_][A-Za-z0-9_]*Array)\\b/g)||[])))];
  const groups=[gl,constants,callbacks,numbers,[...new Set(gl.concat(constants,callbacks,numbers))]];let chosen=[];const primary=groups[variant%groups.length];chosen.push(...primary.slice(0,6));for(const group of groups)for(const token of group)if(chosen.length<6&&!chosen.includes(token))chosen.push(token);
  const answers=[];const html=lines.map((line,lineNo)=>{let out=esc(line);const rawCode=codeLines[lineNo];for(const token of chosen){if(answers.find(a=>a.token===token))continue;const pos=rawCode.indexOf(token);if(pos>=0){const n=answers.length;answers.push({token,answer:token});const escapedPos=esc(line.slice(0,pos)).length;out=out.slice(0,escapedPos)+out.slice(escapedPos).replace(esc(token),'<input class="blank" data-i="'+n+'" placeholder="â€¦"><span class="blank-result" data-r="'+n+'"></span>');break}}return out}).join('\\n');
  return {html:html.replace(/placeholder="[^"]*"/g,'placeholder="..."'),answers,source:s};
}
function buildFillPool(){const sourcesForFill=pickSource().filter(s=>s.code.includes('gl'));fillPool=[];for(const s of sourcesForFill)for(let v=0;v<DB.fillVariants;v++){const b=makeFocusedBlankQuiz(s,v);if(b.answers.length>=3)fillPool.push(b)}fillPool.sort(()=>Math.random()-.5);fillIndex=0}
function renderFillBrowser(){renderSourceBrowser(fillPool.map((b,i)=>({label:'Question '+(i+1)+' · '+b.source.file,meta:b.source.module+' / '+b.source.activity})), 'Fill-in-the-Blank', i=>{fillIndex=i;renderFill()})}
function renderFill(){if(!fillPool.length||fillIndex>=fillPool.length)buildFillPool();renderFillBrowser();const b=fillPool[fillIndex++];const s=b.source;const ref=s.module+' / '+s.activity+' / '+s.file;$('#view').innerHTML='<div class="card"><div class="toolbar"><div><h2 style="margin:0">Fill-in-the-Blank Code Quiz</h2><div class="small">Question '+fillIndex+' of '+fillPool.length+' · Every source file contributes multiple syntax variants.</div></div><button class="btn" id="shuffleFill">Shuffle all questions</button><button class="btn" id="showFill">Show answers</button></div><div class="split" style="margin-top:14px"><div><div class="small">'+esc(ref)+'</div><pre class="code fill-code">'+b.html+'</pre><div class="small">The entire source is complete; only selected syntax tokens are blanked. Scroll the code panel while studying the matching output.</div></div><div>'+(s.image?'<img class="shot" src="'+s.image+'" alt="'+esc(s.imageName||'output screenshot')+'">':'<div class="notice">No matching screenshot was found for this source file.</div>')+'<p class="small">Matching output: '+esc(s.imageName||'none')+'</p></div></div><div class="toolbar" style="margin-top:14px"><button class="btn primary" id="checkFill">Check Answer</button><button class="btn" id="newFill">New code question</button><button class="btn" id="resetFill">Reset blanks</button></div><div id="feedback"></div></div>';
  $('#checkFill').onclick=()=>{const inputs=[...document.querySelectorAll('.blank')];let hits=0;inputs.forEach(x=>{const i=+x.dataset.i;const expected=b.answers[i].answer;const ok=x.value.trim().toLowerCase()===expected.toLowerCase();x.classList.toggle('correct',ok);x.classList.toggle('incorrect',!ok);const tag=document.querySelector('.blank-result[data-r="'+i+'"]');tag.className='blank-result '+(ok?'correct':'incorrect');tag.textContent=ok?'✓':'✗ Correct: '+expected;if(ok)hits++});const ok=hits===inputs.length;record(ok,'Code syntax',{question:'Fill blanks in '+ref,answer:b.answers.map(x=>x.answer).join(', ')});$('#feedback').innerHTML='<div class="answer '+(ok?'':'wrong')+'"><b>'+hits+' / '+inputs.length+' correct '+(ok?'✓':'— keep studying the red blanks')+'</b><br><span>Green blanks match the real source. Red blanks show the exact correct token beside them.</span><br><span class="small">Code syntax · '+esc(ref)+'</span></div>'};$('#showFill').onclick=()=>document.querySelectorAll('.blank').forEach(x=>{x.value=b.answers[+x.dataset.i].answer;x.classList.add('correct');x.classList.remove('incorrect');const tag=document.querySelector('.blank-result[data-r="'+x.dataset.i+'"]');tag.className='blank-result correct';tag.textContent='✓'});$('#resetFill').onclick=()=>document.querySelectorAll('.blank').forEach(x=>{x.value='';x.classList.remove('correct','incorrect');const tag=document.querySelector('.blank-result[data-r="'+x.dataset.i+'"]');tag.className='blank-result';tag.textContent=''});$('#newFill').onclick=renderFill;$('#shuffleFill').onclick=()=>{fillPool=[];buildFillPool();renderFill()}}
function renderFlash(){if(!flashPool.length||flashIndex>=flashPool.length){flashPool=F.slice().sort(()=>Math.random()-.5);flashIndex=0}const q=flashPool[flashIndex++];$('#view').innerHTML='<div class="card"><h2>Flashcards</h2><div class="small">Card '+flashIndex+' of '+flashPool.length+' · Source-derived syntax and concept review.</div><div class="flash" id="flashQ">'+esc(q[0])+'</div><div id="flashA" class="answer hide"><b>Answer:</b> '+esc(q[1])+'<br>'+esc(q[2])+'</div><div class="actions"><button class="btn primary" id="reveal">Reveal answer</button><button class="btn" id="gotIt">I knew it</button><button class="btn" id="missed">Review again</button><button class="btn" id="flashNew">Next card</button></div><div class="small" style="margin-top:12px">'+esc((q[3]||'OpenGL concepts')+(q[4]?' · '+q[4]:''))+'</div></div>';$('#reveal').onclick=()=>$('#flashA').classList.remove('hide');$('#gotIt').onclick=()=>{record(true,q[3]||'Flashcards', {question:q[0],answer:q[1]});renderFlash()};$('#missed').onclick=()=>{record(false,q[3]||'Flashcards', {question:q[0],answer:q[1]});renderFlash()};$('#flashNew').onclick=renderFlash}
function renderShot(){const items=S.filter(s=>s.image);const s=items[Math.floor(Math.random()*items.length)];const q=['Which source file/activity best matches this output?',s.file,'The screenshot is paired with this real source file by activity token and module folder.','Screenshot recognition',s.id];$('#view').innerHTML='<div class="card"><h2>Screenshot-to-Code Quiz</h2><img class="shot" src="'+s.image+'"><p>Which source file/activity best matches this output?</p><select class="select" id="shotAns" style="width:100%"><option value="">Choose a source</option>'+items.slice().sort(()=>Math.random()-.5).slice(0,8).map(x=>'<option>'+esc(x.file+' — '+x.module+' / '+x.activity)+'</option>').join('')+'</select><div class="toolbar" style="margin-top:12px"><button class="btn primary" id="shotCheck">Check Answer</button><button class="btn" id="shotNew">New Question</button></div><div id="feedback"></div></div>';$('#shotCheck').onclick=()=>{const a=$('#shotAns').value;const ok=a.startsWith(s.file);record(ok,'Screenshot recognition',{question:q[0],answer:q[1]});$('#feedback').innerHTML=answerBox(q,'Screenshot recognition',s.file,'The filename and activity token match the embedded output asset.',s.id,ok)};$('#shotNew').onclick=renderShot}
function renderOrder(){const stmts=['glutInit(&argc, argv);','glutInitWindowSize(600, 600);','glutCreateWindow("OpenGL Activity");','glutDisplayFunc(display);','glutMainLoop();'];const shuffled=stmts.slice().sort(()=>Math.random()-.5);$('#view').innerHTML='<div class="card"><h2>Code-Ordering Quiz</h2><p>Arrange the GLUT setup statements from initialization to event loop.</p><div class="order-list" id="order">'+shuffled.map((x,i)=>'<div class="order-item" draggable="true" data-v="'+esc(x)+'">'+esc(x)+'</div>').join('')+'</div><div class="toolbar" style="margin-top:12px"><button class="btn primary" id="orderCheck">Check Answer</button><button class="btn" id="orderNew">New Question</button></div><div id="feedback"></div></div>';let drag;document.querySelectorAll('.order-item').forEach(x=>{x.ondragstart=()=>drag=x;x.ondragover=e=>e.preventDefault();x.ondrop=()=>{if(drag!==x)x.parentNode.insertBefore(drag,x)}});$('#orderCheck').onclick=()=>{const got=[...document.querySelectorAll('.order-item')].map(x=>x.dataset.v);const ok=got.join('|')===stmts.join('|');record(ok,'Program structure',{question:'Arrange GLUT setup',answer:stmts.join(' → ')});$('#feedback').innerHTML=answerBox({},'Program structure',stmts.join(' → '),'Initialize GLUT, configure the window, create it, register the display callback, then enter glutMainLoop.', 'Any Module 1–4 main function',ok)};$('#orderNew').onclick=renderOrder}
function renderDebug(){const q=['Fix the mistake: the program calls glBegin(GL_TRIANGLES) but never calls glEnd(). What is missing?','glEnd();','Every glBegin must be paired with glEnd before flushing or issuing unrelated drawing commands.','Debugging'];$('#view').innerHTML='<div class="card"><h2>Debugging Mode</h2><pre class="code">glBegin(GL_TRIANGLES);&#10;glVertex2f(0.0f, 0.6f);&#10;glVertex2f(-0.6f, -0.4f);&#10;glVertex2f(0.6f, -0.4f);&#10;glFlush();</pre><p>'+q[0]+'</p><input class="input" id="answer" style="width:100%" placeholder="Type the missing statement"><div class="toolbar" style="margin-top:12px"><button class="btn primary" id="check">Check Answer</button><button class="btn" id="debugNew">New error</button></div><div id="feedback"></div></div>';$('#check').onclick=()=>{const a=$('#answer').value.trim();const ok=a.replace(/\\s/g,'').toLowerCase()==='glend();';record(ok,'Debugging',{question:q[0],answer:q[1]});$('#feedback').innerHTML=answerBox({},'Debugging',q[1],q[2],'Immediate-mode source files',ok)};$('#debugNew').onclick=renderDebug}
function renderMock(){clearInterval(timer);let left=300;mockEnd=Date.now()+left*1000;quizPool=Q.slice().sort(()=>Math.random()-.5).slice(0,10);quizIndex=0;function tick(){left=Math.max(0,Math.ceil((mockEnd-Date.now())/1000));const t=$('#timer');if(t)t.textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');if(!left){clearInterval(timer);$('#feedback').innerHTML='<div class="answer wrong"><b>Time.</b> Start a new mock exam to continue.</div>'}}$('#view').innerHTML='<div class="card"><div class="toolbar"><div><h2 style="margin:0">Mock Exam Mode</h2><div class="small">10 mixed questions · timed · wrong answers are saved</div></div><b id="timer">5:00</b></div><div class="progress"><i id="mockProgress"></i></div><div id="mockQuestion" style="margin-top:14px"></div><div id="feedback"></div></div>';timer=setInterval(tick,250);tick();show();function show(){if(quizIndex>=quizPool.length){$('#mockQuestion').innerHTML='<h3>Mock complete</h3><p>Review Mistakes to revisit anything you missed.</p>';return}const q=quizPool[quizIndex];$('#mockQuestion').innerHTML='<h3>'+esc((quizIndex+1)+'. '+q[0])+'</h3><input class="input" id="answer" style="width:100%" placeholder="Your answer"><div class="toolbar" style="margin-top:12px"><button class="btn primary" id="check">Check Answer</button></div>';$('#mockProgress').style.width=(quizIndex/quizPool.length*100)+'%';$('#check').onclick=()=>{const a=$('#answer').value.trim();const ok=a.toLowerCase()===String(q[1]).toLowerCase()||String(q[1]).toLowerCase().includes(a.toLowerCase())&&a.length>3;record(ok,q[3]||'Mock exam',{question:q[0],answer:q[1]});$('#feedback').innerHTML=answerBox(q,q[3]||'Mock exam',q[1],q[2],q[4]||'Concept bank',ok);quizIndex++;setTimeout(show,800)}}}
function renderMistakes(){const w=state.wrong||[];$('#view').innerHTML='<div class="card"><h2>Mistakes & Progress</h2><div class="progress"><i style="width:'+(state.answered?state.correct/state.answered*100:0)+'%"></i></div><p class="small">'+state.correct+' correct out of '+state.answered+' answered. Weak topics are counted by missed questions.</p><h3>Review Mistakes</h3>'+(w.length?w.slice(0,30).map(x=>'<div class="answer wrong"><b>'+esc(x.question)+'</b><br>Correct answer: '+esc(x.answer)+'</div>').join(''):'<div class="notice">No mistakes saved yet. Answer a few questions to build your review list.</div>')+'</div>'}
function render(){nav();renderStats();$('#sourceBrowser').innerHTML='';if(mode==='learn')renderLearn();else if(mode==='fill')renderFill();else if(mode==='flash')renderFlash();else renderMistakes()}
$('#theme').onclick=()=>{document.body.classList.toggle('light');state.theme=document.body.classList.contains('light')?'light':'dark';save()};$('#resetProgress').onclick=()=>{if(confirm('Reset saved scores and mistakes?')){localStorage.removeItem('ogl-reviewer-progress');location.reload()}};const refreshFilteredMode=()=>{if(mode==='learn')renderLearn();else if(mode==='fill'){fillPool=[];fillIndex=0;renderFill()}};$('#search').oninput=refreshFilteredMode;$('#moduleFilter').onchange=()=>{filters();refreshFilteredMode()};$('#activityFilter').onchange=refreshFilteredMode;filters();if(state.theme==='light')document.body.classList.add('light');render();
</script>${establishedUi}</body></html>`;
